select jsonb_object_agg(category,data) as snapshot from (
select 'meta' as category, jsonb_build_object('captured_at',now(),'database',current_database(),'role',current_user,'read_only',current_setting('transaction_read_only'),'version',current_setting('server_version')) as data
union all select 'schemas',coalesce(jsonb_agg(jsonb_build_object('name',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl::text) order by nspname),'[]') from pg_namespace where nspname not like 'pg_%' and nspname not in ('information_schema','supabase_migrations')
union all select 'relations',coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'extension',(select e.extname from pg_depend d join pg_extension e on e.oid=d.refobjid where d.classid='pg_class'::regclass and d.objid=c.oid and d.refclassid='pg_extension'::regclass and d.deptype='e'),'comment',obj_description(c.oid,'pg_class'),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'replica_identity',c.relreplident,'acl',c.relacl::text,'options',c.reloptions,'view_definition',case when c.relkind in ('v','m') then pg_get_viewdef(c.oid,true) end) order by n.nspname,c.relname),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname !~ '^pg_' and n.nspname not in ('information_schema','supabase_migrations') and c.relkind in ('r','p','v','m','S','f')
union all select 'columns',coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',a.attname,'comment',col_description(c.oid,a.attnum),'position',a.attnum,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated,'acl',a.attacl::text,'collation',case when a.attcollation<>t.typcollation then col.collname end) order by c.relname,a.attnum),'[]') from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace join pg_type t on t.oid=a.atttypid left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum left join pg_collation col on col.oid=a.attcollation where n.nspname !~ '^pg_' and n.nspname not in ('information_schema','supabase_migrations') and c.relkind in ('r','p','v','m','f') and a.attnum>0 and not a.attisdropped
union all select 'constraints',coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',co.conname,'type',co.contype,'index',case when co.contype in ('p','u','x') then (select ci.relname from pg_class ci where ci.oid=co.conindid) end,'definition',pg_get_constraintdef(co.oid,true),'validated',co.convalidated,'deferrable',co.condeferrable,'deferred',co.condeferred) order by c.relname,co.conname),'[]') from pg_constraint co join pg_namespace n on n.oid=co.connamespace left join pg_class c on c.oid=co.conrelid where n.nspname !~ '^pg_' and n.nspname not in ('information_schema','supabase_migrations')
union all select 'indexes',coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',i.relname,'definition',pg_get_indexdef(x.indexrelid),'valid',x.indisvalid,'ready',x.indisready,'unique',x.indisunique,'primary',x.indisprimary,'replica_identity',x.indisreplident) order by c.relname,i.relname),'[]') from pg_index x join pg_class i on i.oid=x.indexrelid join pg_class c on c.oid=x.indrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname !~ '^pg_' and n.nspname not in ('information_schema','supabase_migrations')
union all select 'routines',coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'comment',obj_description(p.oid,'pg_proc'),'identity',pg_get_function_identity_arguments(p.oid),'result',pg_get_function_result(p.oid),'definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'config',p.proconfig,'acl',p.proacl::text,'kind',p.prokind,'volatility',p.provolatile,'parallel',p.proparallel,'strict',p.proisstrict,'leakproof',p.proleakproof) order by p.proname,pg_get_function_identity_arguments(p.oid)),'[]') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname !~ '^pg_' and n.nspname not in ('information_schema','supabase_migrations') and p.prokind in ('f','p') and not exists (select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e')
union all select 'triggers',coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid,true)) order by c.relname,t.tgname),'[]') from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname !~ '^pg_' and n.nspname not in ('information_schema','supabase_migrations') and not t.tgisinternal
union all select 'policies',coalesce(jsonb_agg(to_jsonb(p) order by p.tablename,p.policyname),'[]') from pg_policies p where p.schemaname !~ '^pg_' and p.schemaname not in ('information_schema','supabase_migrations')
union all select 'types',coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',t.typname,'kind',t.typtype,'labels',(select jsonb_agg(e.enumlabel order by e.enumsortorder) from pg_enum e where e.enumtypid=t.oid),'base_type',case when t.typtype='d' then format_type(t.typbasetype,t.typtypmod) end,'not_null',t.typnotnull,'default',t.typdefault,'owner',pg_get_userbyid(t.typowner),'acl',t.typacl::text) order by t.typname),'[]') from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname !~ '^pg_' and n.nspname not in ('information_schema','supabase_migrations') and t.typtype in ('e','d')
union all select 'roles',coalesce(jsonb_agg(jsonb_build_object('name',rolname,'superuser',rolsuper,'inherit',rolinherit,'create_role',rolcreaterole,'create_db',rolcreatedb,'can_login',rolcanlogin,'replication',rolreplication,'bypass_rls',rolbypassrls,'connection_limit',rolconnlimit,'config',(select jsonb_agg(case when split_part(x,'=',1) in ('search_path','statement_timeout','default_transaction_read_only','log_statement') then x else split_part(x,'=',1)||'=[REDACTED]' end order by x) from unnest(rolconfig) x)) order by rolname),'[]') from pg_roles
union all select 'role_memberships',coalesce(jsonb_agg(jsonb_build_object('role',pg_get_userbyid(roleid),'member',pg_get_userbyid(member),'grantor',pg_get_userbyid(grantor),'admin',admin_option,'inherit',inherit_option,'set',set_option) order by roleid,member),'[]') from pg_auth_members
union all select 'default_privileges',coalesce(jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(d.defaclrole),'schema',n.nspname,'kind',d.defaclobjtype,'acl',d.defaclacl::text) order by d.defaclrole,d.defaclnamespace,d.defaclobjtype),'[]') from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace
union all select 'extensions',coalesce(jsonb_agg(jsonb_build_object('name',e.extname,'schema',n.nspname,'version',e.extversion,'owner',pg_get_userbyid(e.extowner)) order by e.extname),'[]') from pg_extension e join pg_namespace n on n.oid=e.extnamespace
union all select 'publications',coalesce(jsonb_agg(jsonb_build_object('name',pubname,'owner',pg_get_userbyid(pubowner),'all_tables',puballtables,'insert',pubinsert,'update',pubupdate,'delete',pubdelete,'truncate',pubtruncate) order by pubname),'[]') from pg_publication
union all select 'publication_tables',coalesce(jsonb_agg(to_jsonb(p) order by p.pubname,p.schemaname,p.tablename),'[]') from pg_publication_tables p
union all select 'other_relations',coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind) order by n.nspname,c.relname),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname not like 'pg_%' and n.nspname not in ('public','information_schema','supabase_migrations') and c.relkind in ('r','p','v','m','S','f')
union all select 'sequences',coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'type',format_type(s.seqtypid,null),'start',s.seqstart,'increment',s.seqincrement,'min',s.seqmin,'max',s.seqmax,'cache',s.seqcache,'cycle',s.seqcycle,'owned_by',(select jsonb_build_object('schema',nn.nspname,'table',cc.relname,'column',a.attname,'dependency',d.deptype) from pg_depend d join pg_class cc on cc.oid=d.refobjid join pg_namespace nn on nn.oid=cc.relnamespace join pg_attribute a on a.attrelid=cc.oid and a.attnum=d.refobjsubid where d.classid='pg_class'::regclass and d.objid=c.oid and d.refclassid='pg_class'::regclass and d.deptype in ('a','i') limit 1)) order by n.nspname,c.relname),'[]') from pg_sequence s join pg_class c on c.oid=s.seqrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname !~ '^pg_' and n.nspname not in ('information_schema','supabase_migrations')
union all select 'database_config',jsonb_build_object('encoding',pg_encoding_to_char(d.encoding),'collation',d.datcollate,'ctype',d.datctype,'owner',pg_get_userbyid(d.datdba),'acl',d.datacl::text,'role_settings',(select jsonb_agg(jsonb_build_object('role',case when s.setrole=0 then 'ALL' else pg_get_userbyid(s.setrole) end,'settings',(select jsonb_agg(case when split_part(x,'=',1) in ('search_path','statement_timeout','app.settings.jwt_exp','pgrst.db_schemas','pgrst.db_extra_search_path') then x else split_part(x,'=',1)||'=[REDACTED]' end order by x) from unnest(s.setconfig) x))) from pg_db_role_setting s where s.setdatabase=d.oid)) from pg_database d where d.datname=current_database()
union all select 'event_triggers',coalesce(jsonb_agg(jsonb_build_object('name',evtname,'event',evtevent,'enabled',evtenabled,'owner',pg_get_userbyid(evtowner),'function',evtfoid::regproc::text,'tags',evttags) order by evtname),'[]') from pg_event_trigger
union all select 'rules',coalesce(jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'name',rulename,'definition',definition) order by schemaname,tablename,rulename),'[]') from pg_rules where schemaname !~ '^pg_' and schemaname not in ('information_schema','supabase_migrations') and rulename<>'_RETURN'
union all select 'foreign_servers',coalesce(jsonb_agg(jsonb_build_object('name',srvname,'owner',pg_get_userbyid(srvowner),'wrapper',(select fdwname from pg_foreign_data_wrapper w where w.oid=s.srvfdw),'option_keys',(select jsonb_agg(split_part(x,'=',1)) from unnest(srvoptions) x)) order by srvname),'[]') from pg_foreign_server s
union all select 'view_dependencies',coalesce(jsonb_agg(distinct jsonb_build_object('schema',n.nspname,'view',v.relname,'depends_schema',dn.nspname,'depends_on',drel.relname)),'[]') from pg_rewrite r join pg_class v on v.oid=r.ev_class join pg_namespace n on n.oid=v.relnamespace join pg_depend d on d.classid='pg_rewrite'::regclass and d.objid=r.oid and d.refclassid='pg_class'::regclass join pg_class drel on drel.oid=d.refobjid join pg_namespace dn on dn.oid=drel.relnamespace where n.nspname='public' and v.relkind in ('v','m') and drel.oid<>v.oid
) catalog;
